INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7cdec527-8daa-4bdd-8f3f-6e01d4096a9c', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$121. óra: Kördiagram$q$, $q$Kördiagram értelmezése, körcikkek szöge, százalékos megoszlás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "6e1a804a-3cfe-4b32-9cd3-5130aa55ef86", "text": "Mire szolgál a kördiagram?", "type": "multiple-choice", "options": [{"id": "5a1455e0-2977-4fae-9030-70d43de33246", "text": "Az egyes részek teljes egészhez (100%) viszonyított arányának szemléltetésére", "isCorrect": true}, {"id": "d4abc735-5553-404e-bacd-a45a840e4c26", "text": "Vonalak összekötésére", "isCorrect": false}, {"id": "4d7c6285-fff5-4312-80f8-98875b2dba39", "text": "Pontok rajzolására", "isCorrect": false}, {"id": "f367300d-b032-4ebe-94a6-e316c8a08ccb", "text": "Időbeli növekedés ábrázolására", "isCorrect": false}], "timeLimit": 15}, {"id": "30289e84-cdea-4836-8ed2-d49d9939fc54", "text": "Hány fokos a kördiagram teljes köre (100%)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "a4f87155-92ca-4b4a-b7c9-1edd9f8dd50c", "text": "Hány fokos körcikk tartozik az 50%-os (fél) részhez? (360 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "2d19a70c-13ec-4d35-9520-ecc770dde8ca", "text": "Hány fokos körcikk tartozik a 25%-os (negyed) részhez? (360 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "a704b49d-153a-4292-be0d-4abb09ce8e20", "text": "Hány fokos körcikk tartozik a 10%-os részhez? (360 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "8a19fa9e-a407-4604-b79c-0118f6227e4e", "text": "A kördiagramon a körcikkek középponti szögei egyenesen arányosak a képviselt százalékkal.", "type": "true-false", "options": [{"id": "fdcee966-2701-4dac-8fae-1dccdaf9e08f", "text": "Igaz", "isCorrect": true}, {"id": "8ffe4da4-3ae0-47b6-8dda-4e590ace9f8d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2c709224-2945-407e-b433-07f129f51b26", "text": "A körcikkek szögeinek összege mindig 360°.", "type": "true-false", "options": [{"id": "1e303f1a-c3c0-4141-a488-eea12f4314e1", "text": "Igaz", "isCorrect": true}, {"id": "da1361ef-993c-4940-86a8-1359e3bee24c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('82f40096-5af9-4d5c-97d1-330a138b8358', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$122. óra: Adatok ábrázolása, átlag$q$, $q$Számtani közép (átlag) kiszámítása és ábrázolás digitális eszközzel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "03210612-79e9-49eb-9512-cd30bc9d4bc2", "text": "Hogyan számítjuk ki több szám számtani középértékét (átlagát)?", "type": "multiple-choice", "options": [{"id": "fd4c54b0-898a-498c-ba1e-1ebae73cfa53", "text": "Összeadjuk az adatokat, majd az összeget elosztjuk az adatok darabszámával", "isCorrect": true}, {"id": "ad93c3da-186e-4f6f-9617-5938e741c59d", "text": "Megszorozzuk az adatokat", "isCorrect": false}, {"id": "92607e83-c6c2-4dee-bf0b-9f12518ff6e2", "text": "Kivonjuk a legkisebbet a legnagyobból", "isCorrect": false}, {"id": "9229ea8d-d4e8-42a5-8b3d-65d09542cd27", "text": "Kiválasztjuk a leggyakoribb számot", "isCorrect": false}], "timeLimit": 15}, {"id": "397156ce-7bd1-4c7f-bb95-f252a99bdfbb", "text": "Mennyi a 4, 6, 8, 10 számok átlaga? (28 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "ba78810b-a7a7-4598-b548-94ef01b85e59", "text": "Mennyi a 10, 20, 30, 40, 50 számok átlaga? (150 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "9b403d7c-b285-42e1-8e2b-2cfca108c783", "text": "Egy diák osztályzatai: 5, 4, 5, 5, 3. Mennyi a tanulmányi átlaga? (22 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.4"}, {"id": "3b12ab63-72b5-4e56-9451-f0733de22c92", "text": "Az átlag értéke mindig a legkisebb és a legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "776261e6-1dd3-46b4-ac80-0f3fdef8ccda", "text": "Igaz", "isCorrect": true}, {"id": "a737e8ef-f977-4cf3-9069-59971682c9c0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b63ac971-5966-4800-8afc-28febe2dc581", "text": "Digitális táblázatkezelőben (pl. Excel) az ÁTLAG (AVERAGE) függvény azonnal kiszámolja az átlagot.", "type": "true-false", "options": [{"id": "24208626-bf3c-459e-92ec-c1f6fc4f5202", "text": "Igaz", "isCorrect": true}, {"id": "b898ef09-44e9-4b06-b537-430e909162f6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b213058d-221c-4881-bbf9-15d101f62c29", "text": "Mennyi a 15 és 25 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('25b9d949-276c-48f7-be78-ae8538782312', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$123. óra: Dobáljunk kockákat!$q$, $q$Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "20a6e2de-3172-4568-9c39-5de8320fa017", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "2f7b3721-2a62-41fa-bf64-10471c8c72ff", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "cc653941-7c00-4b33-9571-974e9fa67e1d", "text": "1 a 2-ből", "isCorrect": false}, {"id": "17320792-4dfe-4f76-b79d-39b8fb3d3e4e", "text": "100%", "isCorrect": false}, {"id": "b944cc7e-088d-4a3c-b30d-b9c80617b2f0", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "f2b5b283-0535-4fa0-8131-ae68096cc2d9", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "7b9bcbd6-4eb7-4905-8104-3ef89af1ed7a", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "eda97a2c-a656-405d-9311-06e392760e12", "text": "1/6", "isCorrect": false}, {"id": "31a0e2ef-0db1-416e-967a-2cad17b2ac5a", "text": "2/6", "isCorrect": false}, {"id": "9135fd3b-013d-47e9-921d-7aa75d76ce23", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "e4d61f3b-d45e-46ca-af43-e367c1765c6b", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "1c31141e-50ed-4c64-b5e7-9e68912c41e7", "text": "Igaz", "isCorrect": true}, {"id": "f207d60e-8776-41e0-a34f-b2fb45e2beeb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "94ba52d1-f57a-48b3-9a12-be0fc3aee842", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "a64f065a-36c7-4db1-a42c-79cb89b798f7", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "218675a9-251d-4010-8886-a9de716e7222", "text": "Biztos esemény", "isCorrect": false}, {"id": "22c07eba-6f0c-409e-b5d5-1a9e9fd4d463", "text": "Lehetséges", "isCorrect": false}, {"id": "7a4405f6-9fd4-4fac-b96e-746a5ce6fb80", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "33b9d997-2408-43cb-9f03-fd96e21be2b1", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "c369782b-c653-4092-9b96-3c910930884b", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "174c020c-1dd7-4264-bc9a-1d15fafe0900", "text": "Lehetetlen", "isCorrect": false}, {"id": "d78b6d63-6cff-49ec-94f7-10a5904b7709", "text": "Kétes", "isCorrect": false}, {"id": "2916108f-075f-490e-b818-ee1000ab63f3", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "985549db-aca9-401b-868e-ca89b8eeeece", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "be05f859-d202-4a4f-9ccc-9f0f5f53be46", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "58e8407e-b4be-4568-9807-d459fa3b5414", "text": "Igaz", "isCorrect": true}, {"id": "3d6b4fbb-0088-4a1c-98d3-af1e8327bec3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0ffbcd51-55a0-4461-8c6a-b6a62d7a8369', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$124. óra: Dobáljunk pénzérmét!$q$, $q$Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "4b3bc81f-555b-4734-abac-3eea90b56d0c", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "cbcd717a-94ee-4543-82da-b402d732eb9a", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "2ee5db61-1294-443f-a9e3-82ad31e88f79", "text": "1/4", "isCorrect": false}, {"id": "be7735b4-b024-46bd-9e71-498e8fdde121", "text": "100%", "isCorrect": false}, {"id": "659deed0-825f-4f92-ab9b-9eb8a416f054", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "57e59d0b-d839-409c-9eb0-73bc8b7eeaf2", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "1abb759c-1221-42cf-a0d8-7b816e7dc0c0", "text": "Igaz", "isCorrect": true}, {"id": "3388019f-560f-47c9-a59c-521f9ba58177", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8cb95d97-4a37-44ef-a7f1-2ea6ec059909", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "16eb384e-2327-48d6-9700-b6e8c576432b", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "a93f3152-a831-49de-89ac-deb958614ef8", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "b1c06f20-2731-4c63-ab2e-2aa1ab17ab90", "text": "Igaz", "isCorrect": true}, {"id": "5c8d25d9-fdc7-4294-81fc-8eb2ce4f3b1d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f5faf315-6f74-4c8c-89ab-d828ec596f5f", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "9ed64e89-aef1-4123-b9fc-dad38bf6c5a3", "text": "Igaz", "isCorrect": true}, {"id": "a2425a3f-696e-4eb8-b150-dce76c75b1da", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d55eb68-006a-4084-bdf2-9d147acbdf5f", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "0a594897-a090-4a54-a7a8-864516564e72", "text": "Igaz", "isCorrect": true}, {"id": "01e8e977-c799-4232-8054-876c61d19588", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ee2445b5-00b9-4428-934b-005b46442bbd', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$125. óra: Összefoglalás$q$, $q$Statisztikai és valószínűségi ismeretek összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "b68aa115-0a1e-428f-a3dc-fe2780c10ef0", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "3f1f48fd-17a6-4fc2-b9c4-0ea05b8b72a9", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "ce146b5e-8428-4367-a306-72041764bdc9", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "5682ad97-8922-4015-91b2-3b7f63ed76d1", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "58f7d6b1-c8fc-4198-bf8d-a23c43b25559", "text": "Igaz", "isCorrect": true}, {"id": "3de1d027-f1b7-4ca1-a7e8-e4e85874d624", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d4768883-77e9-4445-970a-59e96368b6f4", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "875830b7-d24d-4fa2-89ad-427617f1d910", "text": "Igaz", "isCorrect": true}, {"id": "604ee1af-8391-4b05-b209-4f98c4846db4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dbbe392c-e386-486f-a284-4753250369e4", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "593b55e4-3be4-4744-8408-5adc74c2a371", "text": "Vonaldiagram", "isCorrect": true}, {"id": "a8aee15c-16d8-449e-b2ee-c834f48b601f", "text": "Kördiagram", "isCorrect": false}, {"id": "8034869a-5f7c-41c8-9abc-f4e9d48c2727", "text": "Pontdiagram", "isCorrect": false}, {"id": "2099e6dd-0b56-45be-aa22-81299be04996", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "8348a1db-81b7-4235-af9f-6454aec6db90", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('83497a48-af32-4cc0-8a5b-0d5c729b3e7a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$126. óra: Számonkérés$q$, $q$Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "fb7c6cb7-2a56-4a34-970a-ea28d004d90a", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "7f93515e-e4db-414b-a551-41d7d0ae25bb", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "38a82c3b-8ae8-4769-81fc-3817882622e7", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "266a98d0-d836-4f67-927a-b7e54522c845", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "b2a990df-305c-4e83-99f8-7e0f6079307f", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "512410bb-2ed4-4c87-960f-f3fa79c7eb0b", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "7b872f14-42df-4c22-8f4c-f1a6f558ba04", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "2544b7df-ef5e-4b29-8e71-7d137252b7ba", "text": "Biztos esemény", "isCorrect": false}, {"id": "8707306a-7d45-45ce-9c8d-132202a94c5f", "text": "Lehetséges", "isCorrect": false}, {"id": "de0b72e9-793f-4cdd-9742-29aca83be1af", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "49e19a05-7553-47aa-a593-59e85c63d19c", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "9f0e96c9-5af1-4beb-9449-b60cb7d79b75", "text": "Biztos esemény", "isCorrect": true}, {"id": "359c89a7-4bbb-4f4e-88b4-04493f5b0223", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "71a35548-89db-48bb-b24f-b01a41129b5f", "text": "Ritka", "isCorrect": false}, {"id": "65c4f141-cacf-4fba-a8a2-9d892075783e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "347e0a9c-4c29-4bd2-a5ca-6706d1d481aa", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "43dbd4fe-e422-4a6d-bc29-21771f9ff73c", "text": "Igaz", "isCorrect": true}, {"id": "c5be7b42-0e1f-4c2e-b02d-644772377bbe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dadf2291-ddca-4b5b-9c65-1bb959a95c69", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "528fba92-0d2d-4d55-b93c-d12dcddf73bd", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "dd369550-4a31-4893-a94a-8e44729f1243", "text": "Igaz", "isCorrect": true}, {"id": "2cedca19-3def-43f8-b4e7-7c87e6913cb6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('507b411e-31d7-42ea-a171-9e5453024c2e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$127. óra: A számonkérés értékelése$q$, $q$A statisztikai feladatok és projektmunkák megbeszélése, értékelése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Statisztika$q$, $q$[{"id": "0cbde3c0-530b-4dd5-975a-aeec35e0cd16", "text": "Mi volt a projektmunka és a számonkérés legfőbb tanulsága?", "type": "multiple-choice", "options": [{"id": "a45a7780-9028-4439-ba15-0e71e3a41165", "text": "Az adatok pontos rögzítése és a helyes skálázás elengedhetetlen a helyes diagramokhoz", "isCorrect": true}, {"id": "7f31cef2-90bb-429d-a1fd-857b1d709f19", "text": "A rajzolás nem fontos", "isCorrect": false}, {"id": "832734b1-10c3-47b3-9226-91459560aaf6", "text": "A számolást el kell hagyni", "isCorrect": false}, {"id": "4cb0f607-9cdb-4ea1-ac4f-2e90367a689f", "text": "Mindegy a skála", "isCorrect": false}], "timeLimit": 15}, {"id": "93729aa8-2a0f-454f-86aa-f7f8b993b277", "text": "Az átlag kiszámításánál a darabszámmal való osztást nem szabad elfelejteni.", "type": "true-false", "options": [{"id": "4561d174-e961-40ba-8383-89ba41d48e94", "text": "Igaz", "isCorrect": true}, {"id": "f19c46a0-d31c-4e07-928b-527c2cad737d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3541b573-d4ce-41de-9d65-71560801cde7", "text": "Mennyi a 12 és 18 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "74398fac-491e-47f7-837d-46bd69103052", "text": "A kördiagram körcikkei összefüggenek a százalékos megoszlással.", "type": "true-false", "options": [{"id": "96751889-140f-4c12-9c29-2c14fab1e69a", "text": "Igaz", "isCorrect": true}, {"id": "adc3f400-bb7d-4d5b-bf35-6190ae192066", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "20da4138-7349-4745-9a89-e1f74eaa1f9c", "text": "A kísérletek során nyert adatok segítenek megérteni a valószínűségi elveket.", "type": "true-false", "options": [{"id": "afa57b51-21df-40da-9233-3d6f5305e3b0", "text": "Igaz", "isCorrect": true}, {"id": "9446cec5-9379-4f4f-99a7-e3530ab4914e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "12562cd2-c619-498f-9644-0f0f538f4133", "text": "Mennyi a 5, 10, 15 átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "4f53f44f-d0b1-423e-8aa1-b79e1c88a60e", "text": "A csoporteredmények bemutatása fejlesztette a kommunikációs készséget.", "type": "true-false", "options": [{"id": "9aea318b-52ce-4d08-8e69-568d4d801804", "text": "Igaz", "isCorrect": true}, {"id": "e43af13a-7a49-4937-9842-a11f3f87e7c3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('24b96835-ed25-4a0b-9c43-b075797ed34b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$128. óra: Mindennapi pénzügyeink I.$q$, $q$Alapvető pénzügyi fogalmak: megtakarítás, kamat, kamatláb, futamidő, bankbetét.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Mindennapi pénzügyeink$q$, $q$[{"id": "ff9aa7ac-cd09-4775-ad3a-d2e0eb20f947", "text": "Mit jelent a banki megtakarítás (betét) után járó 'kamat'?", "type": "multiple-choice", "options": [{"id": "70d93b65-c3ad-4ea1-a11d-49f4584484bf", "text": "A bank által a lekötött pénz használatáért fizetett plusz összeg", "isCorrect": true}, {"id": "9537daa6-7b0e-4ab1-9008-5bd800507ba9", "text": "A bankkezelési díj", "isCorrect": false}, {"id": "5f798331-3ba0-4eae-a2e6-c2edc900361a", "text": "A büntetés", "isCorrect": false}, {"id": "663f8133-4456-4b91-a088-17a0e82a8284", "text": "A fizetett adó", "isCorrect": false}], "timeLimit": 15}, {"id": "c6e62bcb-bfc9-4b17-9e32-da35ce2fa0e6", "text": "Ha 100 000 Ft-ot beteszünk a bankba 5%-os éves kamatra, hány Ft kamatot kapunk 1 év múlva? (100000 * 0,05)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5000"}, {"id": "cbd10bbe-ad67-403b-9ff6-3397b38dd356", "text": "Mennyi pénzünk lesz a bankban az 1 év letelte után a 100 000 Ft betét és a 5000 Ft kamat összegeként?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "105000"}, {"id": "96e9eef4-c1a2-471a-92e0-cfcd315797b7", "text": "A futamidő az az időtartam, ameddig a pénzünket a bankban lekötjük.", "type": "true-false", "options": [{"id": "d1abf576-640b-4991-8a11-8ef561178202", "text": "Igaz", "isCorrect": true}, {"id": "2e9e98aa-cb75-4c88-afd4-50824fcd6040", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "239569c0-2b68-4b3f-bbfa-b301ffac275a", "text": "A hitel felvételekor nekünk kell kamatot fizetnünk a banknak a kölcsönzött pénzért.", "type": "true-false", "options": [{"id": "a4d22dc8-f9b7-4129-a01b-2ab4f3cdf954", "text": "Igaz", "isCorrect": true}, {"id": "b880aa7a-d325-4c3a-887b-2242a5e4664d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d211860-556f-4407-8559-58844b3b785d", "text": "A megtakarítás segít a váratlan kiadások fedezésében és jövőbeli célok megvalósításában.", "type": "true-false", "options": [{"id": "a11dfb92-9f76-456f-86a5-dc3482cf1a84", "text": "Igaz", "isCorrect": true}, {"id": "072b464a-8504-4e4c-9018-dc82b9c380aa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "66cb207b-8d8b-4843-b42a-a3afccd9ed1b", "text": "Mennyi 200 000 Ft 10%-os éves kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b63e873e-5fc7-4482-9546-81b083690844', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$129. óra: Mindennapi pénzügyeink II.$q$, $q$Devizák, valutavételi és -eladási árfolyam, valutaváltás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Mindennapi pénzügyeink$q$, $q$[{"id": "f5605158-b878-4b25-937b-44fd6a1ea2be", "text": "Mit jelent a valuta és deviza árfolyama?", "type": "multiple-choice", "options": [{"id": "87b2aba0-0d2f-4cbb-814a-858b8d5bb98b", "text": "Egy külföldi pénznem (pl. Euró, Dollár) ára hazai pénzben (Ft-ban)", "isCorrect": true}, {"id": "3c695ed1-65af-47ed-90c5-aa14071d5b54", "text": "A bankjegy színe", "isCorrect": false}, {"id": "ecd993eb-e130-4d01-9aea-46d2d3d80894", "text": "A pénz súlya", "isCorrect": false}, {"id": "1fe9d9d3-1539-4e62-beb4-b6b51f7a86fd", "text": "A bank nyitvatartása", "isCorrect": false}], "timeLimit": 15}, {"id": "0d16d184-4300-48b0-9e53-f98c006f2567", "text": "Ha 1 Euró (EUR) eladási árfolyama 400 Ft, hány Ft-ba kerül 50 Euró vásárlása? (50 * 400)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}, {"id": "82245456-e7bb-488f-987c-b281f5e3146f", "text": "Ha 100 Eurót váltunk át Ft-ra 400 Ft/EUR vételi árfolyamon, hány Ft-ot kapunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40000"}, {"id": "5b83c2e7-82e5-4fd5-9472-3071a7c2e368", "text": "A bankok eladási árfolyama magasabb, mint a vételi árfolyam (ebből származik a váltási haszon).", "type": "true-false", "options": [{"id": "e6fc2662-5794-4c4a-806d-3637cbbd9730", "text": "Igaz", "isCorrect": true}, {"id": "0fe9d39a-6564-45eb-b615-5ac2f8ba96d6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "76fd6b61-d78b-4d4e-947c-2224afc83bac", "text": "Melyik a közös európai pénznem jele és neve?", "type": "multiple-choice", "options": [{"id": "56bfc245-db3c-41cf-9f6d-ab99c4d516de", "text": "EUR (€) - Euró", "isCorrect": true}, {"id": "167713ca-913c-4ce2-97fc-bcc1966bf6ec", "text": "USD ($) - Dollár", "isCorrect": false}, {"id": "21091927-8653-42b2-a38f-bcfe337050fd", "text": "GBP (£) - Font", "isCorrect": false}, {"id": "46e3b1c0-1a17-46b9-ab9f-d01045a28fde", "text": "HUF (Ft) - Forint", "isCorrect": false}], "timeLimit": 15}, {"id": "97411f6b-afbf-4326-ba5d-5a5e4a46eec6", "text": "Külföldi utazás előtt érdemes tájékozódni a hivalatos árfolyamokról.", "type": "true-false", "options": [{"id": "f9487a88-97f8-4fad-8797-c2b12b352c37", "text": "Igaz", "isCorrect": true}, {"id": "540f51a9-a7f3-4a29-82a6-0242f829edb0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bbe17609-e5ae-4aa0-a02f-403ad99213b8", "text": "Hány Ft 10 Dollár (USD), ha 1 USD = 350 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('eabd37ca-c567-4a25-9af7-af7b20583322', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$130. óra: Az egész számokról tanultak összefoglalása, vegyes feladatok$q$, $q$Év végi ismétlés: műveletek egész számokkal, előjelek, abszolút érték, ellentett.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év végi ismétlés$q$, $q$[{"id": "18076355-225e-404e-9ee9-a81007cb783b", "text": "Mennyi (-15) + (+25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "dd668140-b977-4d0f-8697-be506c74fa84", "text": "Mennyi (-8) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "56"}, {"id": "bd2fb90b-47e6-43ec-8ca0-67f500b26cee", "text": "Mennyi (-63) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "ffbb81e4-3201-4ae7-9f95-0a705d9a7aa2", "text": "Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "102f80de-c624-443e-906c-49a108336ab8", "text": "Igaz", "isCorrect": true}, {"id": "2dcd197c-c8a8-44d4-b3ee-a8942b7922e9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e88d69a1-c932-4a5a-8006-a59492b108d5", "text": "Mennyi |-40|?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "2b8d0162-d175-446b-8012-c81213b8e0c9", "text": "Melyik szám nagyobb: -12 vagy -4?", "type": "multiple-choice", "options": [{"id": "caf7981c-108f-4432-b2e4-942b7adbf3e2", "text": "-4", "isCorrect": true}, {"id": "a2c0d8a0-b2f8-45d0-93a4-e64bacd33489", "text": "-12", "isCorrect": false}, {"id": "1d33ce53-7291-4417-bdbb-63bb0e04da3d", "text": "Egyenlők", "isCorrect": false}, {"id": "7acb1da3-ed5f-4ea1-b45e-e1fc22e78618", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}, {"id": "41647dd2-d798-461b-a2dd-7f137fb59f9c", "text": "Mennyi (-5) * (-2) * (-3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;